-- Seed regions, games, pokemon, and origin game mappings.
-- Update this file directly when adding new reference data.

ON CONFLICT (name) DO UPDATE SET
  "releaseOrder" = EXCLUDED."releaseOrder",
  "updatedAt" = NOW();

ON CONFLICT (id) DO UPDATE SET
  "displayName" = EXCLUDED."displayName",
  "regionId" = EXCLUDED."regionId",
  region = EXCLUDED.region,
  "releaseYear" = EXCLUDED."releaseYear",
  "updatedAt" = NOW();

ON CONFLICT (id) DO UPDATE SET
  "gameId" = EXCLUDED."gameId",
  "displayName" = EXCLUDED."displayName",
  "sortOrder" = EXCLUDED."sortOrder",
  "isDlc" = EXCLUDED."isDlc",
  "parentDexId" = EXCLUDED."parentDexId",
  "updatedAt" = NOW();

;

ON CONFLICT ("pokemonId", "gameId") DO NOTHING;

ON CONFLICT ("dexId", "pokemonId") DO UPDATE SET
  "dexNumber" = EXCLUDED."dexNumber",
  notes = EXCLUDED.notes;
